 const isCommandant=accountRole==='owner';const canAdmin=['owner','moderator','admin'].includes(accountRole);let mode=isCommandant?'admin':'member',activeConversation='general',chatUnsubscribe=null,stopped=false;
 let civilIdentities={},civilIdentitiesLoaded=false;let members=[],terrains=[],events=[],conversations=[],memberships={},invitations=[],announcements=[],polls=[],messages=[],prefs={messages:true,groups:true,events:true},catalog={grades:['Commandement général','Colonel','Opérateur','Adjudant','Sergent','Caporal','Recrue'],specialities:['Sniper','Éclaireur','Assaut','Soutien','Médic','Démineur']};
