  const hasAnnouncements=announcements.some(a=>!acks[a.id]);
  const hasPolls=!isCommandant&&featureView()&&polls.some(p=>!((currentVotes[p.id]||[]).some(v=>v.id===uid)));
  const hasEvents=!isCommandant&&featureView()&&events.some(e=>e.startsAt?.toMillis?.()>Date.now()&&(!responses[e.id]||(e.instructionsVersion>1&&(instructionReads[e.id]||0)<e.instructionsVersion)));
  for(const [page,on] of [['messages',hasChat],['home',hasAnnouncements||hasPolls],['agenda',hasEvents],['events',hasEvents]]){
   const b=document.querySelector('nav [data-page="'+page+'"]');if(b){b.classList.toggle('gib-has-unread',on);b.setAttribute('aria-label',(b.textContent||page).trim()+(on?' — nouveaux éléments':''));}
  }
