 function rows(s){return s.docs.map(d=>({...d.data(),id:d.id}));}
 function parisTime(value){const m=/^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d)$/.exec(value);if(!m)throw Error('Date ou heure invalide.');const desired=Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+m[5]);const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});let time=desired;for(let i=0;i<3;i++){const parts=Object.fromEntries(fmt.formatToParts(new Date(time)).map(p=>[p.type,p.value]));const represented=Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute);time+=desired-represented;}const p=Object.fromEntries(fmt.formatToParts(new Date(time)).map(p=>[p.type,p.value]));if(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`!==value)throw Error('Cette heure n’existe pas en Europe/Paris (changement d’heure).');return new Date(time);}
