 function renderUpcoming(){if(!featureView()){$('upcomingCard').innerHTML='<h2>Agenda suspendu</h2><p>Fais valider ta cotisation pour retrouver cet accès.</p>';return;}const next=events.filter(e=>e.startsAt.toMillis()>Date.now()&&(e.types||[e.type]).includes('Partie')).sort((a,b)=>a.startsAt.toMillis()-b.startsAt.toMillis())[0];const card=$('upcomingCard');if(!next){card.innerHTML=`<h2>${icon('calendar')} Prochaine partie</h2><p>Aucune partie à venir n’est encore publiée.</p><p class="note">Les réunions et autres rendez-vous restent disponibles dans l’agenda.</p><button class="hero-button" data-shortcut="agenda">${icon('calendar')} Voir l’agenda</button>`;return;}const date=next.startsAt.toDate().toLocaleDateString('fr-FR',{timeZone:'Europe/Paris',weekday:'long',day:'numeric',month:'long'}),r=responses[next.id],closed=Date.now()>=next.closesAt.toMillis(),full=next.yesUids.length>=next.capacity;card.innerHTML=`<h2>${icon('calendar')} Prochaine partie</h2><h3>${esc(next.name)}</h3><div class="event-meta"><p>${icon('calendar')}<strong>${esc(date)} · ${esc(next.time)}</strong></p><p>${icon('map')}${esc(next.place)}</p><p>${icon('users')}<span><strong>${next.yesUids.length}</strong> / ${next.capacity} participants</span></p></div><button class="hero-button" data-rsvp="yes" data-event="${esc(next.id)}" ${isCommandant||closed||full&&r!=='yes'?'disabled':''}>${icon('check')} ${r==='yes'?'Je participe':closed?'Réponses closes':full?'Partie complète':'Je participe'}</button><p class="note">Billet HelloAsso à réserver séparément.</p>`;}
