 function membershipLabel(id){const m=memberships[id];if(!m)return 'Non renseignée';const today=new Intl.DateTimeFormat('fr-CA',{timeZone:'Europe/Paris'}).format(new Date());return m.validated&&m.start<=today&&today<=m.end?'À jour jusqu’au '+m.end:m.validated?'Hors période de validité':'Non validée';}
 function renderProfile(){const me=members.find(m=>m.id===uid);$('greetingName').textContent=nickname(uid);$('profileName').textContent=nickname(uid);$('profileMode').textContent=admin()?'Modérateur':'Membre G.I.B.';$('heroGrade').textContent=me?.grade||'Non renseigné';$('heroSpeciality').textContent=me?.speciality.join(' / ')||'Non renseignées';$('nickname').value=nickname(uid);$('myAssignedInfo').innerHTML=`<p><b>Grade attribué :</b> ${esc(me?.grade||'Non renseigné')}</p><p><b>Spécialisations attribuées :</b> ${esc(me?.speciality.join(', ')||'Non renseignées')}</p>`;$('myMembershipInfo').textContent='Adhésion : '+membershipLabel(uid);$('helloassoMembershipSummary').textContent='Statut enregistré : '+membershipLabel(uid)+'. HelloAsso n’est pas synchronisé.';}
 function renderTerrains(){$('terrainList').innerHTML=terrains.map(t=>{const valid=typeof t.lat==='number'&&typeof t.lon==='number';const url=valid?'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(t.lat+','+t.lon):'';return `<article class="tile"><h3>${icon('map')} ${esc(t.name)}</h3><p>${valid?esc(window.gibGPS.format(t.lat,t.lon)):'GPS à renseigner'}<br>${esc(t.address)}<br>${esc(t.access)}</p><div class="actions">${valid?`<a class="button" href="${url}" target="_blank" rel="noopener noreferrer">Itinéraire / carte ↗</a>`:'<button disabled>GPS non renseigné</button>'}${admin()?`<button class="secondary" data-edit-terrain="${esc(t.id)}">Modifier</button><button class="danger" data-delete-terrain="${esc(t.id)}">Retirer</button>`:''}</div></article>`;}).join('');if(!terrains.length)$('terrainList').innerHTML='<p>Aucun terrain enregistré.</p>';const chosen=$('eventTerrain').value;$('eventTerrain').innerHTML='<option value="">Choisir un terrain enregistré…</option><option value="other">Autre / Aucun terrain</option>'+terrains.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');$('eventTerrain').value=chosen==='other'||terrains.some(t=>t.id===chosen)?chosen:'';}
