 function eventDays(e){const first=e.date,last=e.endDate||e.date;if(!/^\d{4}-\d{2}-\d{2}$/.test(first)||!/^\d{4}-\d{2}-\d{2}$/.test(last)||last<first)return [first];const out=[];let d=new Date(first+'T12:00:00Z');for(let i=0;i<31&&d.toISOString().slice(0,10)<=last;i++,d.setUTCDate(d.getUTCDate()+1))out.push(d.toISOString().slice(0,10));return out;}
 function dayLabel(d){return new Date(d+'T12:00:00Z').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});}
 function attendancePicker(e,closed,started,full){const dates=eventDays(e);if(dates.length<2)return '';const chosen=responseDays[e.id]||((responses[e.id]==='yes')?dates:[]);const locked=closed||started;return `<div class="gib-days"><strong>Quels jours seras-tu présent ?</strong><label class="gib-day"><input type="checkbox" data-all-days="${esc(e.id)}" ${chosen.length===dates.length?'checked':''} ${locked?'disabled':''}> Tous les jours</label>${dates.map(day=>`<label class="gib-day"><input type="checkbox" data-attend-day="${esc(e.id)}" value="${esc(day)}" ${chosen.includes(day)?'checked':''} ${locked?'disabled':''}> ${esc(dayLabel(day))}</label>`).join('')}<p class="note">${chosen.length?'Jours choisis : '+chosen.length+' / '+dates.length:'Sélectionne au moins un jour pour confirmer OUI.'}</p></div>`;}
