 async function setPinned(id){if(!admin())return;const room=conversations.find(c=>c.id===activeConversation);if(!room)return;if(id&&room.pinnedMessageId&&room.pinnedMessageId!==id&&!confirm('Remplacer le message actuellement épinglé ?'))return;const roomId=activeConversation;await F.runTransaction(db,async tx=>{const r=ref('conversations',roomId),snap=await tx.get(r);if(!snap.exists()||snap.data().deleting===true)throw Error('Salon indisponible.');if(id){const m=await tx.get(ref('conversations',roomId,'messages',id));if(!m.exists())throw Error('Le message n’existe plus.');}tx.update(r,{pinnedMessageId:id||''});});notice(id?'Message épinglé.':'Message désépinglé.');}
