 function renderReplyComposer(){const box=$('gibReplyPreview');if(!box)return;if(!replyTarget){box.hidden=true;box.innerHTML='';return;}box.hidden=false;box.innerHTML=`<span><strong>Réponse à ${esc(nickname(replyTarget.authorId))}</strong> · ${esc((replyTarget.text||'📷 Photo').slice(0,110))}</span><button type="button" data-cancel-reply title="Annuler la réponse">×</button>`;box.querySelector('[data-cancel-reply]').onclick=e=>{e.preventDefault();e.stopImmediatePropagation();replyTarget=null;box.hidden=true;box.replaceChildren();};}
