 $('inviteForm').onsubmit=action(async e=>{e.preventDefault();if(!admin())return;const f=new FormData(e.target),address=String(f.get('email')).trim().toLowerCase(),r=f.get('inviteRole');if(address===email.toLowerCase())throw Error('Le compte principal possède déjà son accès.');if(r==='moderator'){if(accountRole!=='owner')return;await F.runTransaction(db,async tx=>{const slots=await Promise.all(['1','2','3','4','5','6'].map(id=>tx.get(ref('moderators',id))));if(slots.some(s=>s.exists()&&s.data().email===address))throw Error('Cette adresse possède déjà une place.');if(!inviteSlot||slots[Number(inviteSlot)-1].exists())throw Error('Place déjà occupée. Actualise et réessaie.');tx.set(ref('moderators',inviteSlot),{email:address,uid:''});tx.set(ref('invitations',address),{role:'moderator',slot:inviteSlot,enabled:true,createdAt:stamp()});});}else await F.setDoc(ref('invitations',address),{role:'member',enabled:true,createdAt:stamp()});$('inviteResult').textContent='Invitation préparée pour '+address+'. Envoie-lui le lien ci-dessous ; il devra utiliser cette adresse et la vérifier. Aucun e-mail automatique n’est envoyé.';const input=document.createElement('input');input.readOnly=true;input.value=location.origin+location.pathname;input.onclick=()=>input.select();$('inviteResult').append(input);e.target.reset();$('invitePanel').classList.add('hidden');});
 let helloassoDashboardStop=null;
 function installHelloassoDashboard(){
  if(!isCommandant||!$('duesControls')||$('helloassoDashboard'))return;
  const panel=document.createElement('article');panel.className='tile';panel.id='helloassoDashboard';
  panel.innerHTML='<h2>HelloAsso — suivi automatique</h2><p id="helloassoDashboardContent">Chargement du rapport…</p><p class="note">Rapport global uniquement. Les restrictions automatiques restent désactivées tant que les échéances individuelles ne sont pas rapprochées des comptes.</p>';
  $('duesControls').parentNode.insertBefore(panel,$('duesControls'));
  helloassoDashboardStop=F.onSnapshot(ref('helloassoDiagnostics','current'),snap=>{
   const box=$('helloassoDashboardContent');if(!box)return;
   if(!snap.exists()){box.textContent='Aucun rapport publié. Lance la synchronisation GitHub Actions.';return;}
   const d=snap.data();let states=[];
   try{states=JSON.parse(d.etatsJson||'[]');}catch(e){states=[];}
   const fmt=states.map(x=>esc(x.etat)+': '+Number(x.nombre||0)).join(' · ');
   box.innerHTML='<strong>'+Number(d.commandes||0)+' commandes · '+Number(d.articles||0)+' articles · '+Number(d.references_paiements||0)+' échéances</strong><p>'+fmt+'</p><p class="note">Dernière mise à jour : '+esc(d.misAJour?.toDate?.().toLocaleString('fr-FR')||'inconnue')+'</p>';
  },err=>{const box=$('helloassoDashboardContent');if(box)box.textContent='Rapport indisponible : vérifie les règles Firestore.';console.warn('Rapport HelloAsso',err);});
 }
 let helloassoStatuses={};
 function helloassoInfo(id){const h=helloassoStatuses[id];if(!h)return '<p class="note">HelloAsso : adhésion non associée ou en attente de synchronisation.</p>';
 let states={};try{states=JSON.parse(h.paymentStatesJson||'{}')}catch{}
 return `<p><b>HelloAsso</b> · adhésion associée</p><p>Référence(s) : ${esc(h.orderIds||'—')} · ${esc(h.paymentCount||0)} échéances référencées</p><p>Statuts : ${esc(Object.entries(states).map(([k,v])=>({Authorized:'Autorisé',Pending:'En attente',Captured:'Encaissé',Paid:'Payé',Succeeded:'Réussi',Failed:'Échoué',Refused:'Refusé',Cancelled:'Annulé',Canceled:'Annulé',Refunded:'Remboursé',PartiallyRefunded:'Partiellement remboursé'}[k]||k)+' : '+v).join(' · ')||'Non renseignés')}</p><p class="note">Paiements à vérifier : les échéances en attente ne sont pas des impayés confirmés.</p>`;
 }
 function renderDues(){installHelloassoDashboard();const term=$('duesSearch').value.toLowerCase();$('duesSearch').hidden=!admin();$('duesHelp').textContent=admin()?'Sélectionne un membre pour enregistrer ou modifier sa cotisation.':'Ta cotisation est consultable ici. Sa validation est réservée aux responsables.';$('duesList').innerHTML=members.filter(m=>(admin()||m.id===uid)&&m.nickname.toLowerCase().includes(term)).map(m=>{const c=memberships[m.id];return `<article class="tile"><h3>${esc(nickname(m.id))}</h3><p>${esc(membershipLabel(m.id))}</p>${c?`<p>${esc(c.amount)} € · ${esc(c.period)} · ${esc(c.method)}</p>`:''}${helloassoInfo(m.id)}${admin()?`<button data-edit-membership="${esc(m.id)}">Enregistrer / modifier la cotisation</button>${m.id!==uid&&(!accessList.some(a=>a.id===m.id&&a.role!=='member'))&&(c?.validated!==true||restrictions[m.id]?.suspended)?`<button class="secondary" data-suspend-member="${esc(m.id)}">${restrictions[m.id]?.suspended?'Lever la suspension':'Suspendre les accès hors générale'}</button>`:''}${restrictions[m.id]?.suspended?'<p>Suspension activée pour cotisation non validée ; accès rétablis dès validation.</p>':''}`:''}</article>`;}).join('')||'<p>Aucune cotisation à afficher.</p>';}
